document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("vat-form"),t=document.getElementById("vat-result"),n=e=>Number(e).toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2});e.addEventListener("submit",function(i){i.preventDefault();let r=parseFloat(e["price-net"].value),s=parseFloat(e["price-gross"].value),a=parseFloat(e["vat-rate"].value);if(isNaN(r)||isNaN(a))if(isNaN(s)||isNaN(a)){if(isNaN(s)||isNaN(r))return t.innerHTML='<span style="color:red;">Please enter any two values</span>',void 0;a=100*(s/r-1)}else r=s/(1+a/100);else s=r*(1+a/100);const l=s-r;t.innerHTML=`\n      <h3>VAT Calculation Results:</h3>\n      <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px; border-left: 4px solid #007bff;">\n        <ul style="list-style:none;padding-left:0;margin:0;">\n          <li><strong>Price without VAT:</strong> ${n(r)}</li>\n          <li><strong>VAT Amount:</strong> ${n(l)}</li>\n          <li><strong>Price with VAT:</strong> ${n(s)}</li>\n          <li><strong>VAT Rate:</strong> ${a.toFixed(2)}%</li>\n        </ul>\n      </div>\n    `})});